<template>
	<view class="gallery-page">
		<view class="gallery-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="header-row">
				<view class="back-button" @click="goBack"><view class="back-arrow" /></view>
				<text class="header-title">我的礼物馆</text>
				<view class="header-space" />
			</view>
		</view>
		<view :style="{ height: headerHeight + 'px' }" />

		<scroll-view class="gallery-scroll" scroll-y :show-scrollbar="false" :style="{ height: scrollHeight + 'px' }">
			<view class="gallery-hero">
				<text class="hero-kicker">GIFT COLLECTION</text>
				<text class="hero-title">每一份心意，都在这里发光</text>
				<text class="hero-copy">收到过的礼物会被永久点亮，即使礼物暂时下架也会留在馆中。</text>
				<view class="collection-progress">
					<view class="progress-copy"><text>已点亮</text><text><strong>{{ summary.unlockedCount }}</strong> / {{ summary.total }}</text></view>
					<view class="progress-track"><view class="progress-value" :style="{ width: progressPercent + '%' }" /></view>
				</view>
			</view>

			<view class="filter-row">
				<view class="filter-item" :class="{ active: activeFilter === 'all' }" @click="activeFilter = 'all'">全部 {{ summary.total }}</view>
				<view class="filter-item" :class="{ active: activeFilter === 'unlocked' }" @click="activeFilter = 'unlocked'">已点亮 {{ summary.unlockedCount }}</view>
			</view>

			<view v-if="loading" class="state-panel">正在整理礼物馆</view>
			<view v-else-if="!visibleGifts.length" class="state-panel">还没有点亮的礼物</view>
			<view v-else class="gift-grid">
				<view v-for="gift in visibleGifts" :key="gift.id" class="gift-item" :class="{ locked: !gift.unlocked }">
					<view class="gift-image-wrap">
						<image class="gift-image" :src="gift.staticImageUrl" mode="aspectFit" />
						<view v-if="!gift.unlocked" class="gift-lock"><text>?</text></view>
						<view v-else class="gift-lit">已点亮</view>
					</view>
					<text class="gift-name">{{ gift.name }}</text>
					<text v-if="gift.unlocked" class="gift-meta">收到 {{ gift.receivedCount }} 次</text>
					<text v-else class="gift-meta">等待相遇</text>
					<view class="gift-tags">
						<text v-if="gift.memberOnly">VIP</text>
						<text v-if="gift.status !== 'active'" class="offline">珍藏款</text>
					</view>
				</view>
			</view>
			<view class="bottom-space" />
		</scroll-view>
	</view>
</template>

<script>
import { fetchGiftGallery } from '../../api/gift';
import { showRequestError } from '../../utils/feedback';

export default {
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 90,
			scrollHeight: 600,
			loading: false,
			activeFilter: 'all',
			summary: { items: [], total: 0, unlockedCount: 0 }
		};
	},
	computed: {
		visibleGifts() {
			return this.activeFilter === 'unlocked'
				? this.summary.items.filter((gift) => gift.unlocked)
				: this.summary.items;
		},
		progressPercent() {
			if (!this.summary.total) return 0;
			return Math.min(100, Math.round(this.summary.unlockedCount / this.summary.total * 100));
		}
	},
	onLoad() {
		const info = uni.getSystemInfoSync();
		const rpxToPx = Number(info.windowWidth || 375) / 750;
		this.statusBarHeight = Number(info.statusBarHeight || 44);
		this.headerHeight = this.statusBarHeight + Math.round(92 * rpxToPx);
		this.scrollHeight = Math.max(320, Number(info.windowHeight || 700) - this.headerHeight);
		this.loadGallery();
	},
	onShow() {
		if (this.summary.items.length) this.loadGallery(true);
	},
	methods: {
		async loadGallery(silent = false) {
			if (!silent) this.loading = true;
			try {
				const result = await fetchGiftGallery();
				this.summary = {
					items: Array.isArray(result && result.items) ? result.items : [],
					total: Number(result && result.total || 0),
					unlockedCount: Number(result && result.unlockedCount || 0)
				};
			} catch (error) {
				showRequestError(error, '礼物馆加载失败');
			} finally {
				this.loading = false;
			}
		},
		goBack() { uni.navigateBack(); }
	}
};
</script>

<style lang="scss" scoped>
.gallery-page { height: 100vh; overflow: hidden; background: #fff8fa; color: #4c3f47; }
.gallery-header { position: fixed; z-index: 10; top: 0; left: 0; right: 0; background: rgba(255,248,250,.97); border-bottom: 1rpx solid #f3e7eb; }
.header-row { display: flex; align-items: center; justify-content: space-between; height: 92rpx; padding: 0 24rpx; box-sizing: border-box; }.back-button, .header-space { width: 60rpx; height: 60rpx; }.back-button { display: flex; align-items: center; justify-content: center; }.back-arrow { width: 18rpx; height: 18rpx; margin-left: 8rpx; border-left: 3rpx solid #a46b80; border-bottom: 3rpx solid #a46b80; transform: rotate(45deg); }.header-title { color: #513d48; font-size: 30rpx; font-weight: 700; }
.gallery-scroll { width: 100%; }.gallery-hero { margin: 20rpx 24rpx 0; padding: 34rpx 30rpx 30rpx; border: 1rpx solid #f2dfe6; border-radius: 16rpx; background: linear-gradient(135deg, #fff0f5 0%, #fffaf4 58%, #f4fff9 100%); box-sizing: border-box; box-shadow: 0 10rpx 28rpx rgba(127,82,101,.07); }.hero-kicker { display: block; color: #ca829e; font-size: 18rpx; font-weight: 700; }.hero-title { display: block; margin-top: 12rpx; color: #583d49; font-size: 34rpx; font-weight: 800; }.hero-copy { display: block; margin-top: 13rpx; color: #9b7e8a; font-size: 22rpx; line-height: 1.55; }
.collection-progress { margin-top: 26rpx; }.progress-copy { display: flex; align-items: baseline; justify-content: space-between; color: #9a7584; font-size: 21rpx; }.progress-copy strong { color: #dc6f96; font-size: 34rpx; }.progress-track { height: 12rpx; margin-top: 12rpx; overflow: hidden; border-radius: 6rpx; background: #f2dfe6; }.progress-value { height: 100%; border-radius: 6rpx; background: linear-gradient(90deg, #ef91ae, #f1b879); transition: width .25s ease; }
.filter-row { display: flex; gap: 14rpx; padding: 26rpx 24rpx 8rpx; }.filter-item { display: flex; align-items: center; justify-content: center; height: 60rpx; padding: 0 25rpx; border: 1rpx solid #eadde2; border-radius: 8rpx; background: #fff; color: #927985; font-size: 23rpx; box-sizing: border-box; }.filter-item.active { border-color: #e987a7; background: #fff0f5; color: #d85f88; font-weight: 700; }
.gift-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18rpx 14rpx; padding: 18rpx 24rpx 0; }.gift-item { position: relative; min-width: 0; min-height: 270rpx; padding: 15rpx 10rpx 16rpx; border: 1rpx solid #f0e4e8; border-radius: 8rpx; background: #fff; text-align: center; box-sizing: border-box; box-shadow: 0 6rpx 18rpx rgba(97,66,79,.045); }.gift-image-wrap { position: relative; display: flex; align-items: center; justify-content: center; height: 150rpx; overflow: hidden; border-radius: 7rpx; background: #fff8fa; }.gift-image { width: 128rpx; height: 128rpx; }.gift-item.locked .gift-image { opacity: .35; filter: grayscale(1); }.gift-lock { position: absolute; display: flex; align-items: center; justify-content: center; width: 46rpx; height: 46rpx; border-radius: 50%; background: rgba(101,91,96,.72); color: #fff; font-size: 24rpx; font-weight: 700; }.gift-lit { position: absolute; right: 5rpx; bottom: 5rpx; padding: 5rpx 9rpx; border-radius: 7rpx; background: #ef8daa; color: #fff; font-size: 16rpx; }.gift-name { display: block; overflow: hidden; margin-top: 12rpx; color: #55444c; font-size: 23rpx; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }.gift-item.locked .gift-name { color: #aaa0a4; }.gift-meta { display: block; margin-top: 7rpx; color: #bd929f; font-size: 19rpx; }.gift-item.locked .gift-meta { color: #bbb3b6; }.gift-tags { display: flex; align-items: center; justify-content: center; gap: 5rpx; min-height: 28rpx; margin-top: 7rpx; }.gift-tags text { padding: 3rpx 7rpx; border-radius: 5rpx; background: #fff0cf; color: #b4781f; font-size: 15rpx; }.gift-tags .offline { background: #eee9eb; color: #8e8488; }
.state-panel { padding: 110rpx 0; color: #b49da6; font-size: 24rpx; text-align: center; }.bottom-space { height: calc(44rpx + env(safe-area-inset-bottom)); }
</style>
